declare
 m jsonb := $manifest${"batch":"sail-result-2026-2026-10-22","officialSource":{"id":180534,"url":"https://www.racingrulesofsailing.org/documents/180534","title":"Official capitan-s-cup-bc88 result document 180534","type":"pdf","visuallyReviewed":true,"provisional":false,"page":1,"pages":[1],"comparison":"All source race scores, discard markers and codes extracted from reviewed official tables; row arithmetic reconciled.","secondaryUrl":"https://sail-result.com/result_detail.html?event=Capitan%27s%20Cup%20BC88"},"event":{"id":"7d19a7bb-7d99-5e90-9010-bbe7ff188710","slug":"capitans-cup-bc88-2026","name":"Capitan's Cup BC88 2026","startDate":"2026-03-21","endDate":"2026-03-23","venue":"Boat Club 88 (Thailand), Sittahip, Chonburi","organizer":"Boat Club 88","classes":["ILCA 4","ILCA 6","ILCA 7","Optimist"],"existing":false},"sheet":{"id":"2c3c4744-ed59-5ed5-a70b-17bb09cd7181","slug":"capitans-cup-bc88-2026-ilca7","name":"Capitan's Cup BC88 2026 — ILCA 7","boatClass":"ILCA 7","division":"Open","raceCount":9,"totalFleetSize":3,"countsForRanking":false,"status":"published","entryType":"individual","minParticipants":1,"maxParticipants":1},"results":[{"eventKey":"capitan-s-cup-bc88","boatClass":"ILCA 7","division":"Open","source":{"id":180534,"url":"https://www.racingrulesofsailing.org/documents/180534","title":"Official capitan-s-cup-bc88 result document 180534","type":"pdf","visuallyReviewed":true,"provisional":false,"page":1},"rank":1,"name":"PRAKASIT HONGPRADAB","sailOrBoardNumber":"211365","club":"RTN","school":null,"nationality":"THA","gender":"M","officialBirthYear":1983,"sourceBirthYear":"1983","grossScore":10.0,"nettScore":8.0,"races":[{"raceNumber":1,"score":1.0,"code":null,"discarded":false,"raw":"1.0","sourceRaceLabel":"R1"},{"raceNumber":2,"score":1.0,"code":null,"discarded":false,"raw":"1.0","sourceRaceLabel":"R2"},{"raceNumber":3,"score":1.0,"code":null,"discarded":false,"raw":"1.0","sourceRaceLabel":"R3"},{"raceNumber":4,"score":1.0,"code":null,"discarded":fa